34	/// Emit a one-time deprecation warning when serving-readiness falls back to
35	/// the legacy path because a namespace still contains a legacy card (a
36	/// worker with no declared `worker_type`). Logged once per process to avoid
37	/// spamming the per-request readiness hot path. Remove with the compat shim.
38	fn warn_legacy_readiness_once(model: &str, namespace: &str) {
39	    static LEGACY_READINESS_WARNED: std::sync::Once = std::sync::Once::new();
40	    LEGACY_READINESS_WARNED.call_once(|| {
41	        tracing::warn!(
42	            model = model,
43	            namespace = namespace,
44	            "Serving-readiness in compatibility mode, please upgrade the workers to latest version. This compatibility shim will be removed in a future release."
45	        );
46	    });
47	}
48	
49	/// Per-worker-type detail within a namespace: how many workers of this type are
50	/// live and what peer types it depends on (DNF — a list of alternative AND-sets).
51	#[derive(Debug, Clone, Serialize)]
52	pub struct WorkerTypeReadiness {
53	    pub workers: usize,
54	    pub needs: Vec<Vec<String>>,
55	}
56	
57	/// Worker readiness for one namespace (one deployment) of a model.
58	#[derive(Debug, Clone, Serialize)]
59	pub struct NamespaceReadiness {
60	    pub ready: bool,
61	    #[serde(skip_serializing_if = "Option::is_none")]
62	    pub reason: Option<String>,
63	    /// Worker type (lowercase `worker_type`) → detail. Legacy workers with no
64	    /// declared `worker_type` are not keyed here; see `reason`.
65	    pub worker_types: std::collections::BTreeMap<String, WorkerTypeReadiness>,
66	    pub present: Vec<String>,
67	    pub missing_worker_types: Vec<String>,
68	}
