70	/// Structured worker readiness for a model across all its namespaces — the
71	/// response body of `GET /v1/models/{model}/ready`.
72	#[derive(Debug, Clone, Serialize)]
73	pub struct ModelReadiness {
74	    pub model: String,
75	    pub ready: bool,
76	    #[serde(skip_serializing_if = "Option::is_none")]
77	    pub reason: Option<String>,
78	    pub namespaces: std::collections::BTreeMap<String, NamespaceReadiness>,
79	}
