90	/// Readiness facts for one namespace, from [`Model::evaluate_namespace`].
91	/// Shared by the serving gate and the `/ready` endpoint so they can't diverge.
92	struct NamespaceReadinessEval {
93	    ready: bool,
94	    has_legacy: bool,
95	    legacy_live_workers: usize,
96	    present: std::collections::HashSet<crate::worker_type::WorkerType>,
97	    missing: std::collections::HashSet<crate::worker_type::WorkerType>,
98	    ambiguous: std::collections::HashSet<crate::worker_type::WorkerType>,
99	}
