101	/// A named model backed by one or more WorkerSets.
102	pub struct Model {
103	    name: String,
104	    worker_sets: DashMap<String, Arc<WorkerSet>>,
105	}
106	
107	impl Model {
108	    pub fn new(name: String) -> Self {
109	        Self {
110	            name,
111	            worker_sets: DashMap::new(),
112	        }
113	    }
114	
115	    pub fn name(&self) -> &str {
116	        &self.name
117	    }
118	
119	    /// Add a WorkerSet to this model.
120	    pub fn add_worker_set(&self, namespace: String, worker_set: Arc<WorkerSet>) {
121	        tracing::info!(
122	            model = %self.name,
123	            namespace = %namespace,
124	            "Adding worker set to model"
125	        );
126	        self.worker_sets.insert(namespace, worker_set);
127	    }
128	
129	    /// Check whether a candidate checksum is compatible with an existing WorkerSet
130	    /// identified by `ws_key`.
131	    pub fn is_checksum_compatible(&self, ws_key: &str, candidate_checksum: &str) -> bool {
132	        match self.worker_sets.get(ws_key) {
133	            Some(existing_ws) => existing_ws.mdcsum() == candidate_checksum,
134	            None => true,
135	        }
136	    }
137	
138	    pub fn remove_worker_set(&self, namespace: &str) -> Option<Arc<WorkerSet>> {
139	        let removed = self.worker_sets.remove(namespace).map(|(_, ws)| ws);
140	        if removed.is_some() {
141	            tracing::info!(
142	                model = %self.name,
143	                namespace = %namespace,
144	                remaining_sets = self.worker_sets.len(),
145	                "Removed worker set from model"
146	            );
147	        }
148	        removed
149	    }
150	
151	    pub fn has_worker_set(&self, namespace: &str) -> bool {
152	        self.worker_sets.contains_key(namespace)
153	    }
154	
155	    pub fn get_worker_set(&self, namespace: &str) -> Option<Arc<WorkerSet>> {
156	        self.worker_sets
157	            .get(namespace)
158	            .map(|entry| entry.value().clone())
159	    }
160	
161	    pub fn is_empty(&self) -> bool {
162	        self.worker_sets.is_empty()
163	    }
164	
165	    pub fn worker_set_count(&self) -> usize {
166	        self.worker_sets.len()
167	    }
168	
169	    /// Snapshot all WorkerSets. Used by cross-role lifecycle coordination
170	    /// where storage keys include role/surface suffixes but deployment
171	    /// matching is based on `WorkerSet::namespace()`.
172	    pub(crate) fn worker_sets(&self) -> Vec<Arc<WorkerSet>> {
173	        self.worker_sets
174	            .iter()
175	            .map(|entry| entry.value().clone())
176	            .collect()
177	    }
178	
179	    /// Build an immutable membership snapshot for request-plane publication.
180	    ///
181	    /// WorkerSets themselves are shared because their engines and routing lifecycle are
182	    /// long-lived. The membership map is copied so later discovery mutations cannot leak
183	    /// through an older published catalog.
184	    pub(crate) fn snapshot(&self) -> Self {
185	        let snapshot = Self::new(self.name.clone());
186	        for entry in &self.worker_sets {
187	            snapshot
188	                .worker_sets
189	                .insert(entry.key().clone(), entry.value().clone());
190	        }
191	        snapshot
192	    }
193	
