292	
293	    // -- Model serving readiness --
294	    //
295	    // The set of WorkerSets in this Model that share the same `namespace`
296	    // string collectively serve traffic for one deployment. A worker's
297	    // `needs` is in DNF: a list of alternative AND-sets of required peer
298	    // worker types. The namespace is ready when, for every WorkerSet in it,
299	    // at least one alternative is fully covered by the worker types
300	    // currently present (workers with worker_count > 0).
301	    //
302	
303	    /// Distinct namespaces represented by this model's WorkerSets, sorted.
304	    /// Each namespace identifies one deployment of the model.
305	    pub fn distinct_namespaces_sorted(&self) -> Vec<String> {
306	        let mut ns: Vec<String> = self
307	            .worker_sets
308	            .iter()
309	            .map(|entry| entry.value().namespace().to_string())
310	            .collect();
311	        ns.sort();
312	        ns.dedup();
313	        ns
314	    }
315	
316	    /// Return `(worker_type, needs)` for this WorkerSet, or `None` if the
317	    /// card has no declared `worker_type` (a legacy card from an old,
318	    /// pre-`worker_type` worker). The readiness path treats `None` as the
319	    /// signal to fall back to the cross-version compat path — see
320	    /// `is_workers_ready`.
321	    fn ws_type_and_needs(
322	        ws: &WorkerSet,
323	    ) -> Option<(
324	        crate::worker_type::WorkerType,
325	        Vec<Vec<crate::worker_type::WorkerType>>,
326	    )> {
327	        let card = ws.card();
328	        card.worker_type.map(|wt| (wt, card.needs.clone()))
329	    }
330	
331	    /// Whether the workers in the given namespace are ready to serve traffic.
332	    ///
333	    /// Iterates the WorkerSets sharing this namespace and checks that every
334	    /// WorkerSet's `needs` (DNF) has at least one alternative fully covered
335	    /// by the present worker types. Returns false for an unknown namespace or
336	    /// one with no WorkerSets.
337	    ///
338	    /// **Cross-version compat:** if the namespace still contains a legacy card
339	    /// (a worker with no declared `worker_type`, i.e. an old pre-`worker_type`
340	    /// binary), its disaggregated worker types cannot be reconstructed — old decode
341	    /// and old aggregated workers are indistinguishable on the wire. Rather than
342	    /// hide the model, we fall back to legacy behavior and report ready as long
343	    /// as some worker is live. Strict worker-type readiness gating resumes automatically once
344	    /// every worker in the namespace carries a `worker_type`.
345	    ///
346	    /// TODO(v1.5): Remove this branch with the legacy MDC topology shims after
347	    /// the v1.2 compatibility window expires.
348	    pub fn is_workers_ready(&self, namespace: &str) -> bool {
349	        let wsets: Vec<Arc<WorkerSet>> = self
350	            .worker_sets
351	            .iter()
352	            .filter(|entry| entry.value().namespace() == namespace)
353	            .map(|entry| entry.value().clone())
354	            .collect();
355	        self.evaluate_namespace(&wsets).ready
356	    }
357	
358	    /// Evaluate readiness for one namespace's WorkerSets — the shared check
359	    /// behind both the serving gate and the `/ready` endpoint.
360	    ///
361	    /// Strict (non-legacy) semantics: ready when a worker is live, every
362	    /// registered worker type has a live worker, and every *live* WorkerSet's
363	    /// `needs` DNF is satisfied; anything absent goes in `missing`. A dead
364	    /// WorkerSet's needs are ignored (a live sibling of the same type carries
365	    /// the same `needs`). A legacy card (no `worker_type`) bypasses the strict
366	    /// check: ready iff any worker is live. Empty `wsets` is not ready.
367	    fn evaluate_namespace(&self, wsets: &[Arc<WorkerSet>]) -> NamespaceReadinessEval {
368	        let units = wsets
369	            .iter()
370	            .map(|ws| match Self::ws_type_and_needs(ws) {
371	                Some((worker_type, needs)) => super::readiness::ReadinessUnit {
372	                    worker_type: Some(worker_type),
373	                    live_count: ws.worker_count(),
374	                    needs,
375	                },
376	                None => super::readiness::ReadinessUnit {
377	                    worker_type: None,
378	                    live_count: ws.worker_count(),
379	                    needs: Vec::new(),
380	                },
381	            })
382	            .collect::<Vec<_>>();
383	        let eval = super::readiness::evaluate_readiness(&units);
384	        if eval.has_legacy {
385	            warn_legacy_readiness_once(&self.name, wsets[0].namespace());
386	        }
387	        NamespaceReadinessEval {
388	            ready: eval.ready,
389	            has_legacy: eval.has_legacy,
390	            legacy_live_workers: eval.legacy_live_workers,
391	            present: eval.present,
392	            missing: eval.missing,
393	            ambiguous: eval.ambiguous,
394	        }
395	    }
396	
397	    /// Return the namespace identifier of the first ready set of workers (in
398	    /// sorted order), or `None` if none are ready.
399	    pub fn first_ready_workers(&self) -> Option<String> {
400	        self.distinct_namespaces_sorted()
401	            .into_iter()
402	            .find(|ns| self.is_workers_ready(ns))
403	    }
404	
405	    /// Whether at least one namespace's worker set in this model is ready to
406	    /// serve traffic.
407	    pub fn has_ready_workers(&self) -> bool {
408	        self.first_ready_workers().is_some()
409	    }
410	
411	    /// Structured per-namespace worker readiness for this model — the data
412	    /// behind the `GET /v1/models/{model}/ready` observability endpoint.
413	    ///
414	    /// Built on the same `Self::evaluate_namespace` facts the serving gate
415	    /// uses, so the reported `ready`/`missing` can never disagree with routing;
416	    /// this method only layers display data (per-type counts, reason strings).
417	    pub fn namespace_readiness(&self) -> ModelReadiness {
418	        let mut namespaces = std::collections::BTreeMap::new();
419	
420	        for ns in self.distinct_namespaces_sorted() {
421	            let wsets: Vec<Arc<WorkerSet>> = self
422	                .worker_sets
423	                .iter()
424	                .filter(|entry| entry.value().namespace() == ns)
425	                .map(|entry| entry.value().clone())
426	                .collect();
427	
428	            // Authoritative readiness facts (shared with the serving gate).
429	            let eval = self.evaluate_namespace(&wsets);
430	
431	            // Display layer: per-type live-worker counts and declared `needs`.
432	            let mut worker_types: std::collections::BTreeMap<String, WorkerTypeReadiness> =
433	                std::collections::BTreeMap::new();
434	            for ws in &wsets {
435	                let card = ws.card();
436	                if let Some(wt) = card.worker_type {
437	                    let entry = worker_types
438	                        .entry(wt.as_str().to_string())
439	                        .or_insert_with(|| WorkerTypeReadiness {
440	                            workers: 0,
441	                            needs: card
442	                                .needs
443	                                .iter()
444	                                .map(|alt| alt.iter().map(|t| t.as_str().to_string()).collect())
445	                                .collect(),
446	                        });
447	                    entry.workers += ws.worker_count();
448	                }
449	            }
450	
451	            let mut present_vec: Vec<String> = eval
452	                .present
453	                .iter()
454	                .map(|wt| wt.as_str().to_string())
455	                .collect();
456	            present_vec.sort();
457	            let mut missing_vec: Vec<String> = eval
458	                .missing
459	                .iter()
460	                .map(|wt| wt.as_str().to_string())
461	                .collect();
462	            missing_vec.sort();
463	
464	            let reason = if eval.ready {
465	                if eval.has_legacy {
466	                    let legacy_live_workers = eval.legacy_live_workers;
467	                    Some(format!(
468	                        "legacy worker(s) present (no worker_type); readiness gating bypassed \
469	                         (ready while {legacy_live_workers} worker(s) live) — compat window only"
470	                    ))
471	                } else {
472	                    None
473	                }
474	            } else if eval.has_legacy {
475	                Some("legacy worker(s) present but no live worker".to_string())
476	            } else if !eval.ambiguous.is_empty() {
477	                let mut roles = eval
478	                    .ambiguous
479	                    .iter()
480	                    .map(|worker_type| worker_type.as_str())
481	                    .collect::<Vec<_>>();
482	                roles.sort_unstable();
483	                Some(format!("ambiguous worker types: {}", roles.join(", ")))
484	            } else {
485	                Some(format!("missing worker types: {}", missing_vec.join(", ")))
486	            };
487	
488	            namespaces.insert(
489	                ns.clone(),
490	                NamespaceReadiness {
491	                    ready: eval.ready,
492	                    reason,
493	                    worker_types,
494	                    present: present_vec,
495	                    missing_worker_types: missing_vec,
496	                },
497	            );
498	        }
499	
500	        let ready = namespaces.values().any(|n| n.ready);
501	        ModelReadiness {
502	            model: self.name.clone(),
503	            ready,
504	            reason: if ready {
505	                None
506	            } else {
507	                Some("no namespace has all required worker types live".to_string())
508	            },
509	            namespaces,
510	        }
511	    }
512	
513	    /// Whether this model can serve at least one inference request right now.
514	    ///
515	    /// Differs from [`Self::is_displayable`] in that it does **not** fall back
516	    /// to prefill-only WorkerSets: requires a WorkerSet that has a serving
517	    /// engine attached and workers connected.
518	    /// Used by KServe gRPC `model_ready` / `server_ready` to avoid the race
519	    /// where a `ModelDeploymentCard` is registered before its WorkerSet has
520	    /// been wired up.
521	    ///
522	    /// Delegates to `Self::select_worker_set_with` so readiness reports
523	    /// exactly what request routing would accept — including the namespace
524	    /// completeness gate. Without that, a live decode-only WorkerSet with a
525	    /// chat engine but no prefill peer would report ready while every request
526	    /// was rejected.
527	    pub fn is_ready_to_serve(&self) -> bool {
528	        self.select_worker_set_with(|ws| ws.has_any_serving_engine().then_some(()))
529	            .is_some()
530	    }
531	
532	    /// Whether this model should be visible in /v1/models.
533	    pub fn is_displayable(&self) -> bool {
534	        let any_set_has_engine = self
535	            .worker_sets
536	            .iter()
537	            .any(|entry| entry.value().has_any_serving_engine());
538	
539	        self.worker_sets.iter().any(|entry| {
540	            let ws = entry.value();
541	            if ws.worker_count() == 0 {
542	                return false;
543	            }
544	            ws.has_any_serving_engine() || (!any_set_has_engine && ws.is_prefill_set())
545	        })
546	    }
