680	
681	    /// Get load threshold config from the first WorkerSet that has a monitor.
682	    /// When `config` is Some, updates ALL monitors (each WorkerSet has its own).
683	    pub fn load_threshold_config(
684	        &self,
685	        config: Option<&LoadThresholdConfig>,
686	    ) -> Option<LoadThresholdConfig> {
687	        let mut result = None;
688	        for entry in self.worker_sets.iter() {
689	            if let Some(ref monitor) = entry.value().worker_monitor {
690	                if let Some(cfg) = config {
691	                    monitor.set_load_threshold_config(cfg);
692	                }
693	                if result.is_none() {
694	                    result = Some(monitor.load_threshold_config());
695	                }
696	            }
697	        }
698	        result
699	    }
