709	    // -- Internal helpers --
710	
711	    /// Return the appropriate error when no servable WorkerSet was found.
712	    /// If the engine exists but no WorkerSet can serve (zero workers, prefill not activated,
713	    /// etc.), return ModelUnavailable (maps to 503). Otherwise ModelNotFound (maps to 404).
714	    fn engine_error(&self, engine_exists: bool) -> ModelManagerError {
715	        if engine_exists {
716	            ModelManagerError::ModelUnavailable(self.name.clone())
717	        } else {
718	            ModelManagerError::ModelNotFound(self.name.clone())
719	        }
720	    }
721	
722	    // -- Internal selection --
723	
724	    /// Select a WorkerSet and extract a value from it.
725	    ///
726	    /// When there's only one set (steady state), returns from that set directly.
727	    /// With multiple sets, uses weighted random selection proportional
728	    /// to worker count, filtering to sets that have the requested engine.
729	    ///
730	    /// The `extract` closure should return `Some(value)` if the WorkerSet has the
731	    /// desired engine, or `None` if it doesn't.
732	    ///
733	    fn select_worker_set_with<T, F>(&self, extract: F) -> Option<T>
734	    where
735	        F: Fn(&WorkerSet) -> Option<T>,
736	    {
737	        // One snapshot drives both the readiness filter and candidate
738	        // eligibility, so a concurrent add/remove can't make us treat a
739	        // namespace as complete while routing to a set that lost a peer. It also
740	        // avoids re-entering the DashMap mid-iteration, which can deadlock.
741	        let snapshot: Vec<Arc<WorkerSet>> = self
742	            .worker_sets
743	            .iter()
744	            .map(|entry| entry.value().clone())
745	            .collect();
746	
747	        // Namespaces whose worker set is complete, evaluated against the snapshot.
748	        let mut namespaces: Vec<&str> = snapshot.iter().map(|ws| ws.namespace()).collect();
749	        namespaces.sort_unstable();
750	        namespaces.dedup();
751	        let ready_namespaces: std::collections::HashSet<&str> = namespaces
752	            .into_iter()
753	            .filter(|ns| {
754	                let in_ns: Vec<Arc<WorkerSet>> = snapshot
755	                    .iter()
756	                    .filter(|ws| ws.namespace() == *ns)
757	                    .cloned()
758	                    .collect();
759	                self.evaluate_namespace(&in_ns).ready
760	            })
761	            .collect();
762	
763	        // Fast path: single set (same zero-worker filtering as the multi-set path below)
764	        if snapshot.len() == 1 {
765	            let ws = &snapshot[0];
766	            if ws.worker_count() == 0 || !ready_namespaces.contains(ws.namespace()) {
767	                return None;
768	            }
769	            return extract(ws);
770	        }
771	
772	        // Collect eligible sets with their worker counts, skipping sets with no workers or sets in
773	        // a namespace whose worker set is incomplete.
774	        // In-process models (no discovery watcher) return count=1, so they always participate.
775	        // Discovery models with count=0 have no available workers and are skipped.
776	        let eligible: Vec<(T, usize)> = snapshot
777	            .iter()
778	            .filter_map(|ws| {
779	                let count = ws.worker_count();
780	                if count == 0 || !ready_namespaces.contains(ws.namespace()) {
781	                    return None;
782	                }
783	                extract(ws).map(|val| (val, count))
784	            })
785	            .collect();
786	
787	        if eligible.is_empty() {
788	            return None;
789	        }
790	
791	        if eligible.len() == 1 {
792	            return eligible.into_iter().next().map(|(val, _)| val);
793	        }
794	
795	        // Weighted random selection proportional to worker count
796	        let total_weight: usize = eligible.iter().map(|(_, w)| w).sum();
797	        let mut pick = rand::rng().random_range(0..total_weight);
798	        for (val, weight) in eligible {
799	            if pick < weight {
800	                return Some(val);
801	            }
802	            pick -= weight;
803	        }
804	        // Should not reach here, but fallback to None
805	        None
806	    }
807	}
