37	struct RequestLifetimeEngine<Req, Resp>
38	where
39	    Req: AsyncEngineContextProvider + Send + 'static,
40	    Resp: AsyncEngineContextProvider + 'static,
41	{
42	    inner: Arc<dyn AsyncEngine<Req, Resp, Error>>,
43	    teardown: Arc<AllocatorTrimOnDrop>,
44	}
45	
46	#[async_trait]
47	impl<Req, Resp> AsyncEngine<Req, Resp, Error> for RequestLifetimeEngine<Req, Resp>
48	where
49	    Req: AsyncEngineContextProvider + Send + 'static,
50	    Resp: AsyncEngineContextProvider + 'static,
51	{
52	    async fn generate(&self, request: Req) -> Result<Resp, Error> {
53	        request.context().retain(self.teardown.clone());
54	        let response = self.inner.generate(request).await?;
55	        response.context().retain(self.teardown.clone());
56	        Ok(response)
57	    }
58	}
