60	fn retain_teardown_until_requests_finish<Req, Resp>(
61	    engine: Option<Arc<dyn AsyncEngine<Req, Resp, Error>>>,
62	    teardown: &Arc<AllocatorTrimOnDrop>,
63	) -> Option<Arc<dyn AsyncEngine<Req, Resp, Error>>>
64	where
65	    Req: AsyncEngineContextProvider + Send + 'static,
66	    Resp: AsyncEngineContextProvider + 'static,
67	{
68	    engine.map(|inner| {
69	        Arc::new(RequestLifetimeEngine {
70	            inner,
71	            teardown: teardown.clone(),
72	        }) as Arc<dyn AsyncEngine<Req, Resp, Error>>
73	    })
74	}
