131	/// A set of workers from the same namespace/configuration with their own pipeline.
132	pub struct WorkerSet {
133	    /// Full namespace (e.g., "ns-abc12345")
134	    namespace: String,
135	
136	    /// Exact serving pool identity. Discovery-backed WorkerSets always set
137	    /// this; in-process models have no distributed endpoint.
138	    endpoint_id: Option<EndpointId>,
139	
140	    /// Endpoint handle used only by committed topology reconciliation.
141	    topology_endpoint: Option<Endpoint>,
142	
143	    /// MDC checksum for this set's configuration
144	    mdcsum: String,
145	
146	    /// The model deployment card used to build this set's pipeline
147	    card: ModelDeploymentCard,
148	
149	    // Engines — each WorkerSet owns its own pipelines
150	    pub(crate) chat_engine: Option<OpenAIChatCompletionsStreamingEngine>,
151	    pub(crate) completions_engine: Option<OpenAICompletionsStreamingEngine>,
152	    pub(crate) embeddings_engine: Option<OpenAIEmbeddingsStreamingEngine>,
153	    pub(crate) classify_engine: Option<OpenAIClassifyStreamingEngine>,
154	    pub(crate) pooling_engine: Option<OpenAIPoolingStreamingEngine>,
155	    pub(crate) images_engine: Option<OpenAIImagesStreamingEngine>,
156	    pub(crate) videos_engine: Option<OpenAIVideosStreamingEngine>,
157	    pub(crate) audios_engine: Option<OpenAIAudiosStreamingEngine>,
158	    pub(crate) tensor_engine: Option<TensorStreamingEngine>,
159	    pub(crate) realtime_engine: Option<RealtimeBidirectionalEngine>,
160	    pub(crate) generate_engine: Option<GenerateStreamingEngine>,
161	
162	    /// Worker monitor for load-based rejection
163	    pub(crate) worker_monitor: Option<KvWorkerMonitor>,
164	
165	    /// Prefill router for disaggregated serving. Stored here so the watcher can
166	    /// deactivate it when all prefill workers die, and reactivate when they rejoin.
167	    pub(crate) prefill_router: Option<Arc<dyn PrefillRouterLifecycle>>,
168	
169	    /// Optional multimodal encoder hop. Stored for discovery-driven
170	    /// deactivation/reactivation when Encode workers leave or rejoin.
171	    pub(crate) encoder_router: Option<Arc<EncoderRouter>>,
172	
173	    /// Watcher for available instance IDs (from the Client's discovery watch).
174	    /// None for in-process models (http/grpc) which don't have a discovery client.
175	    instance_count_rx: Option<watch::Receiver<Vec<u64>>>,
176	
177	    /// Cancels background work created while materializing this WorkerSet.
178	    lifecycle_cancellation: Option<CancellationToken>,
