290	    /// Whether this set has any decode engine (chat or completions)
291	    pub fn has_decode_engine(&self) -> bool {
292	        self.has_chat_engine() || self.has_completions_engine()
293	    }
294	
295	    /// Whether this set has any engine capable of producing output for an
296	    /// inference request. Single source of truth for the "is something attached
297	    /// that can serve a request?" question — keep the engine-kind list here so
298	    /// new modalities don't need to be added in multiple readiness predicates.
299	    pub fn has_any_serving_engine(&self) -> bool {
300	        self.has_chat_engine()
301	            || self.has_completions_engine()
302	            || self.has_embeddings_engine()
303	            || self.has_classify_engine()
304	            || self.has_pooling_engine()
305	            || self.has_images_engine()
306	            || self.has_tensor_engine()
307	            || self.has_videos_engine()
308	            || self.has_audios_engine()
309	            || self.has_realtime_engine()
310	            || self.has_generate_engine()
311	    }
312	
313	    /// Whether this set tracks an Encode worker. Encode WorkerSets carry
314	    /// no serving engines (the watcher's Encode role gate skips
315	    /// pipeline construction) -- if we let `is_prefill_set` classify
316	    /// them, model-displayability logic would gate /v1/models on a
317	    /// PrefillRouter that doesn't exist for Encode. Keep the two
318	    /// mutually exclusive.
319	    ///
320	    /// **Role-based, not engine-field-based.** Unlike `has_chat_engine()`
321	    /// / `has_completions_engine()` / etc. (which inspect typed engine
322	    /// slots on the WorkerSet), `is_encode_set` reads `card.worker_type`
323	    /// directly. The Encode role intentionally has no `encode_engine`
324	    /// field -- Encode workers don't expose a public OpenAI-shaped
325	    /// endpoint, so there is nothing to slot. The role itself is the
326	    /// contract.
327	    pub fn is_encode_set(&self) -> bool {
328	        matches!(
329	            self.card.worker_type,
330	            Some(crate::worker_type::WorkerType::Encode),
331	        )
332	    }
333	
334	    /// Whether this set tracks a prefill model (no engine, just
335	    /// lifecycle). Excludes Encode sets, which also lack engines but
336	    /// are not gated through PrefillRouter.
337	    pub fn is_prefill_set(&self) -> bool {
338	        !self.is_encode_set() && !self.has_any_serving_engine()
339	    }
