341	    /// Build ParsingOptions from this WorkerSet's card configuration.
342	    pub fn parsing_options(&self) -> crate::protocols::openai::ParsingOptions {
343	        crate::protocols::openai::ParsingOptions {
344	            structural_tag_mode: self.card.runtime_config.structural_tag_mode,
345	            structural_tag_scope: self.card.runtime_config.structural_tag_scope,
346	            exclude_tools_when_tool_choice_none: self
347	                .card
348	                .runtime_config
349	                .exclude_tools_when_tool_choice_none,
350	            ..crate::protocols::openai::ParsingOptions::new(
351	                self.card.runtime_config.tool_call_parser.clone(),
352	                self.card.runtime_config.reasoning_parser.clone(),
353	            )
354	        }
355	    }
