357	    /// Number of active workers in this set, derived from the Client's discovery watcher.
358	    /// Returns 1 for in-process models (no watcher) since they always have one local worker.
359	    pub fn worker_count(&self) -> usize {
360	        match &self.instance_count_rx {
361	            Some(rx) => rx.borrow().len(),
362	            None => 1,
363	        }
364	    }
365	
366	    /// Store the instance watcher from the Client's discovery system.
367	    /// Must be called before the WorkerSet is wrapped in Arc.
368	    pub fn set_instance_watcher(&mut self, rx: watch::Receiver<Vec<u64>>) {
369	        self.instance_count_rx = Some(rx);
370	    }
371	
372	    pub(crate) fn set_lifecycle_cancellation(&mut self, cancellation: CancellationToken) {
373	        self.lifecycle_cancellation = Some(cancellation);
374	    }
375	
376	    pub(crate) fn initialize_allocator_trim_on_teardown(&mut self) -> Arc<AllocatorTrimOnDrop> {
377	        self.allocator_trim
378	            .get_or_insert_with(|| Arc::new(AllocatorTrimOnDrop::new()))
379	            .clone()
380	    }
381	
382	    pub(crate) fn enable_allocator_trim_on_teardown(&mut self) {
383	        if self.allocator_trim_wrapped {
384	            return;
385	        }
386	        let teardown = self.initialize_allocator_trim_on_teardown();
387	        macro_rules! retain_for_requests {
388	            ($field:ident) => {
389	                self.$field = retain_teardown_until_requests_finish(self.$field.take(), &teardown);
390	            };
391	        }
392	        retain_for_requests!(chat_engine);
393	        retain_for_requests!(completions_engine);
394	        retain_for_requests!(embeddings_engine);
395	        retain_for_requests!(classify_engine);
396	        retain_for_requests!(pooling_engine);
397	        retain_for_requests!(images_engine);
398	        retain_for_requests!(videos_engine);
399	        retain_for_requests!(audios_engine);
400	        retain_for_requests!(tensor_engine);
401	        retain_for_requests!(realtime_engine);
402	        retain_for_requests!(generate_engine);
403	        self.allocator_trim_wrapped = true;
404	    }
405	
406	    pub(crate) fn adapter_view(&self, card: ModelDeploymentCard) -> Self {
407	        let lora_name = card
408	            .lora
409	            .as_ref()
410	            .expect("adapter views require LoRA metadata")
411	            .name
412	            .clone();
413	        let generate_engine = self.generate_engine.as_ref().map(|inner| {
414	            Arc::new(LoraGenerateEngine {
415	                inner: inner.clone(),
416	                lora_name: lora_name.clone(),
417	            }) as GenerateStreamingEngine
418	        });
419	        let mut view = Self {
420	            namespace: self.namespace.clone(),
421	            endpoint_id: self.endpoint_id.clone(),
422	            topology_endpoint: self.topology_endpoint.clone(),
423	            mdcsum: self.mdcsum.clone(),
424	            card,
425	            chat_engine: lora_context_engine(&self.chat_engine, &lora_name),
426	            completions_engine: lora_context_engine(&self.completions_engine, &lora_name),
427	            embeddings_engine: lora_context_engine(&self.embeddings_engine, &lora_name),
428	            classify_engine: lora_context_engine(&self.classify_engine, &lora_name),
429	            pooling_engine: lora_context_engine(&self.pooling_engine, &lora_name),
430	            images_engine: lora_context_engine(&self.images_engine, &lora_name),
431	            videos_engine: lora_context_engine(&self.videos_engine, &lora_name),
432	            audios_engine: lora_context_engine(&self.audios_engine, &lora_name),
433	            tensor_engine: lora_context_engine(&self.tensor_engine, &lora_name),
434	            // Realtime is bidirectional, so the server-streaming LoRA context wrapper cannot
435	            // inject the adapter identity. Fail closed instead of serving the base weights.
436	            realtime_engine: None,
437	            generate_engine,
438	            worker_monitor: self.worker_monitor.clone(),
439	            prefill_router: self.prefill_router.clone(),
440	            encoder_router: self.encoder_router.clone(),
441	            instance_count_rx: self.instance_count_rx.clone(),
442	            lifecycle_cancellation: None,
443	            allocator_trim: None,
444	            allocator_trim_wrapped: false,
445	        };
446	        if self.allocator_trim.is_some() {
447	            view.enable_allocator_trim_on_teardown();
448	        }
449	        view
450	    }
451	}
