710	    #[test]
711	    fn test_worker_count_with_watcher() {
712	        let mut ws = make_worker_set("ns1", "abc");
713	
714	        // Simulate a discovery watcher with 3 workers
715	        let (tx, rx) = watch::channel(vec![1, 2, 3]);
716	        ws.set_instance_watcher(rx);
717	        assert_eq!(ws.worker_count(), 3);
718	
719	        // Workers leave → count drops
720	        tx.send(vec![1]).unwrap();
721	        assert_eq!(ws.worker_count(), 1);
722	
723	        // All workers gone → count is 0
724	        tx.send(vec![]).unwrap();
725	        assert_eq!(ws.worker_count(), 0);
726	    }
