728	    #[test]
729	    fn test_worker_count_with_empty_watcher() {
730	        // Discovery watcher starts empty (no workers have joined yet)
731	        let mut ws = make_worker_set("ns1", "abc");
732	        let (_tx, rx) = watch::channel::<Vec<u64>>(vec![]);
733	        ws.set_instance_watcher(rx);
734	        assert_eq!(ws.worker_count(), 0);
735	    }
