737	    #[test]
738	    fn test_worker_count_updates_on_join() {
739	        let mut ws = make_worker_set("ns1", "abc");
740	        let (tx, rx) = watch::channel::<Vec<u64>>(vec![]);
741	        ws.set_instance_watcher(rx);
742	        assert_eq!(ws.worker_count(), 0);
743	
744	        // Workers join one by one
745	        tx.send(vec![100]).unwrap();
746	        assert_eq!(ws.worker_count(), 1);
747	
748	        tx.send(vec![100, 200]).unwrap();
749	        assert_eq!(ws.worker_count(), 2);
750	
751	        tx.send(vec![100, 200, 300]).unwrap();
752	        assert_eq!(ws.worker_count(), 3);
753	    }
