755	    // -------------------------------------------------------------------
756	    // Encode-set classification
757	    //
758	    // Encode WorkerSets carry no serving engines (the watcher's role
759	    // gate skips pipeline construction), so the legacy "no engines =
760	    // prefill" rule would misclassify them. is_encode_set distinguishes
761	    // them via card.worker_type and is_prefill_set excludes them so the
762	    // two predicates stay mutually exclusive.
763	    // -------------------------------------------------------------------
764	
765	    fn make_encode_worker_set() -> WorkerSet {
766	        let mut card = ModelDeploymentCard::default();
767	        card.worker_type = Some(crate::worker_type::WorkerType::Encode);
768	        WorkerSet::new("ns1".to_string(), "abc".to_string(), card)
769	    }
770	
771	    #[test]
772	    fn encode_set_is_classified_as_encode_not_prefill() {
773	        let ws = make_encode_worker_set();
774	        assert!(ws.is_encode_set());
775	        // The two predicates must be mutually exclusive: an Encode set
776	        // has no engines but must NOT be classified as prefill, since
777	        // model-displayability logic gates /v1/models on PrefillRouter
778	        // for prefill sets and Encode workers have no such router.
779	        assert!(!ws.is_prefill_set());
780	    }
781	
782	    #[test]
783	    fn non_encode_engineless_set_stays_classified_as_prefill() {
784	        // Regression guard: the existing "engineless = prefill" rule
785	        // must still hold for worker_type = None / Prefill / Decode /
786	        // Aggregated. Only Encode is carved out.
787	        let mut card_none = ModelDeploymentCard::default();
788	        card_none.worker_type = None;
789	        let ws = WorkerSet::new("ns1".to_string(), "abc".to_string(), card_none);
790	        assert!(!ws.is_encode_set());
791	        assert!(ws.is_prefill_set());
792	
793	        for role in [
794	            crate::worker_type::WorkerType::Prefill,
795	            crate::worker_type::WorkerType::Decode,
796	            crate::worker_type::WorkerType::Aggregated,
797	        ] {
798	            let mut card = ModelDeploymentCard::default();
799	            card.worker_type = Some(role);
800	            let ws = WorkerSet::new("ns1".to_string(), "abc".to_string(), card);
801	            assert!(!ws.is_encode_set(), "{:?} should not be Encode", role);
802	            assert!(
803	                ws.is_prefill_set(),
804	                "{:?} should remain prefill-classified",
805	                role
806	            );
807	        }
808	    }
809	}
