256	    fn lora_projection_locked(&self) -> EndpointLoraProjection {
257	        let mut pending: HashMap<EndpointId, HashMap<WorkerWithDpRank, PendingLoraProjection>> =
258	            HashMap::new();
259	        for group in self.discovery_groups.iter() {
260	            for (key, card) in &group.cards {
261	                let Ok(mcid) = ModelCardInstanceId::from_path(key) else {
262	                    continue;
263	                };
264	                let endpoint_id = EndpointId {
265	                    namespace: mcid.namespace.clone(),
266	                    component: mcid.component.clone(),
267	                    name: mcid.endpoint.clone(),
268	                };
269	                let worker = WorkerWithDpRank::new(mcid.instance_id, 0);
270	                let worker_projection = pending
271	                    .entry(endpoint_id)
272	                    .or_default()
273	                    .entry(worker)
274	                    .or_default();
275	                if let Some(capacity) = card.runtime_config.max_gpu_lora_count {
276	                    worker_projection.base_capacities.push(capacity);
277	                }
278	
279	                for (adapter_key, adapter_card) in &group.adapters {
280	                    let Ok(adapter_mcid) = ModelCardInstanceId::from_path(adapter_key) else {
281	                        continue;
282	                    };
283	                    if adapter_mcid.namespace != mcid.namespace
284	                        || adapter_mcid.component != mcid.component
285	                        || adapter_mcid.endpoint != mcid.endpoint
286	                        || adapter_mcid.instance_id != mcid.instance_id
287	                    {
288	                        continue;
289	                    }
290	                    if let Some(lora) = &adapter_card.lora {
291	                        worker_projection
292	                            .adapters
293	                            .insert(lora.name.clone(), lora.clone());
294	                    }
295	                }
296	            }
297	        }
298	
299	        pending
300	            .into_iter()
301	            .map(|(endpoint_id, workers)| {
302	                let workers = workers
303	                    .into_iter()
304	                    .filter_map(|(worker, mut projection)| {
305	                        projection.base_capacities.sort_unstable();
306	                        projection.base_capacities.dedup();
307	                        if projection.base_capacities.len() > 1 {
308	                            tracing::warn!(
309	                                endpoint = %endpoint_id,
310	                                worker_id = worker.worker_id,
311	                                capacities = ?projection.base_capacities,
312	                                "Base MDCs disagree on LoRA capacity; using the conservative minimum"
313	                            );
314	                        }
315	                        let mut loras = projection.adapters.into_values().collect::<Vec<_>>();
316	                        loras.sort_by(|left, right| left.name.cmp(&right.name));
317	                        let mut adapter_capacities = loras
318	                            .iter()
319	                            .filter_map(|lora| lora.max_gpu_lora_count)
320	                            .collect::<Vec<_>>();
321	                        adapter_capacities.sort_unstable();
322	                        adapter_capacities.dedup();
323	                        if adapter_capacities.len() > 1 {
324	                            tracing::warn!(
325	                                endpoint = %endpoint_id,
326	                                worker_id = worker.worker_id,
327	                                capacities = ?adapter_capacities,
328	                                "Adapter MDCs disagree on LoRA capacity; using the conservative minimum"
329	                            );
330	                        }
331	                        let capacity = projection
332	                            .base_capacities
333	                            .first()
334	                            .copied()
335	                            .or_else(|| adapter_capacities.first().copied())
336	                            .or_else(|| (!loras.is_empty()).then_some(4))?;
337	                        Some((worker, LoraWorkerProjection { capacity, loras }))
338	                    })
339	                    .collect();
340	                (endpoint_id, workers)
341	            })
342	            .collect()
343	    }
