345	    fn union_lora_projection(
346	        before: &EndpointLoraProjection,
347	        after: &EndpointLoraProjection,
348	    ) -> EndpointLoraProjection {
349	        let mut union = before.clone();
350	        for (endpoint, workers) in after {
351	            let endpoint_union = union.entry(endpoint.clone()).or_default();
352	            for (worker, projection) in workers {
353	                let Some(existing) = endpoint_union.get_mut(worker) else {
354	                    endpoint_union.insert(*worker, projection.clone());
355	                    continue;
356	                };
357	                existing.capacity = existing.capacity.min(projection.capacity);
358	                let mut loras = existing
359	                    .loras
360	                    .iter()
361	                    .chain(&projection.loras)
362	                    .map(|lora| (lora.name.clone(), lora.clone()))
363	                    .collect::<HashMap<_, _>>()
364	                    .into_values()
365	                    .collect::<Vec<_>>();
366	                loras.sort_by(|left, right| left.name.cmp(&right.name));
367	                existing.loras = loras;
368	            }
369	        }
370	        union
371	    }
