373	    fn publish_lora_projection_locked(&self, projection: EndpointLoraProjection) {
374	        let mut endpoints = self.committed_lora_endpoints.lock();
375	        let next_endpoints = projection.keys().cloned().collect::<HashSet<_>>();
376	        for endpoint_id in endpoints.union(&next_endpoints) {
377	            let workers = projection.get(endpoint_id).cloned().unwrap_or_default();
378	            if let Some(domain) = self.lora_domains.get(endpoint_id) {
379	                domain.state_tracker.replace_endpoint_projection(workers);
380	            } else if !workers.is_empty() {
381	                self.lora_domain(endpoint_id)
382	                    .state_tracker
383	                    .replace_endpoint_projection(workers);
384	            }
385	        }
386	        *endpoints = next_endpoints;
387	        drop(endpoints);
388	        self.prune_idle_lora_domains();
389	    }
390	
391	    fn prune_idle_lora_domains(&self) {
392	        let committed = self.committed_lora_endpoints.lock().clone();
393	        let removable = self
394	            .lora_domains
395	            .iter()
396	            .filter_map(|entry| {
397	                (!committed.contains(entry.key())
398	                    && entry.state_tracker.is_empty()
399	                    && Arc::strong_count(&entry.filter) == 1)
400	                    .then(|| entry.key().clone())
401	            })
402	            .collect::<Vec<_>>();
403	        for endpoint_id in removable {
404	            let Some((_, domain)) = self.lora_domains.remove(&endpoint_id) else {
405	                continue;
406	            };
407	            domain.shutdown();
408	            if let Some((_, feed)) = self.lora_load_feeds.remove(&endpoint_id.to_string()) {
409	                feed.abort();
410	            }
411	        }
412	    }
