441	    /// Remove a Model if it has no remaining WorkerSets.
442	    ///
443	    /// The caller holds `reservation_lock` and publishes the resulting catalog update.
444	    /// Uses atomic remove_if to avoid TOCTOU race between checking is_empty and removing.
445	    fn remove_model_if_empty(&self, model_name: &str) {
446	        if self
447	            .models
448	            .remove_if(model_name, |_, model| model.is_empty())
449	            .is_some()
450	        {
451	            tracing::info!(model_name, "Removed empty model from manager");
452	        }
