454	
455	    /// Add a WorkerSet to a Model under its primary name. Creates the Model if it
456	    /// doesn't exist. Returns `false` (registering nothing) when `model_name` is
457	    /// already reserved as another deployment's alias.
458	    ///
459	    /// The names a live deployment holds — its primary plus every alias — are
460	    /// globally reserved until it is removed, so a later deployment cannot claim
461	    /// any of them, as either a primary or an alias. This is the primary-side
462	    /// mirror of [`Self::register_alias`] (which rejects an alias colliding with a
463	    /// live primary or another primary's alias); together they make name
464	    /// reservation first-come and symmetric across namespaces. A later deployment
465	    /// re-using a name fails loudly rather than silently displacing the owner.
466	    ///
467	    /// Holds `Self::reservation_lock` across the reserved-name check and the
468	    /// insert so the claim is atomic against a concurrent `register_alias` for
469	    /// the same name (a name can never end up both a live primary and an alias).
470	    /// The lock is always taken before any map access, so it never inverts with a
471	    /// DashMap shard lock.
472	    pub fn add_worker_set(&self, model_name: &str, namespace: &str, worker_set: WorkerSet) -> bool {
473	        let _reservation = self.reservation_lock.lock();
474	        if let Some(reserved_by) = self.alias_to_primary.get(model_name) {
475	            tracing::warn!(
476	                model_name,
477	                reserved_by = reserved_by.value().as_str(),
478	                "Model name is already reserved as an alias of another deployment — refusing to \
479	                 register. Choose a different name or remove the conflicting deployment."
480	            );
481	            return false;
482	        }
483	        let model = self.get_or_create_model(model_name);
484	        let topology_namespace = worker_set.namespace().to_string();
485	        model.add_worker_set(namespace.to_string(), Arc::new(worker_set));
486	        self.reconcile_discovery_topology(model_name, &topology_namespace);
487	        self.publish_catalog_locked();
488	        true
489	    }
