491	    /// Add an already-Arc-wrapped WorkerSet to a Model. Creates the Model if it doesn't exist.
492	    /// Used to register the same WorkerSet under multiple model names (aliases).
493	    ///
494	    /// Logs a warning and skips if a *different* primary already owns this name —
495	    /// this guards against operator misconfiguration where two unrelated models
496	    /// declare a colliding alias. The first claim wins; the second is rejected.
497	    pub fn add_worker_set_arc(
498	        &self,
499	        model_name: &str,
500	        namespace: &str,
501	        worker_set: Arc<WorkerSet>,
502	    ) -> bool {
503	        let _reservation = self.reservation_lock.lock();
504	        // Collision check: if `model_name` already exists as a primary (i.e.
505	        // already has worker sets AND is not currently an alias), refuse to
506	        // clobber it. The two facts are read one map at a time — the `models`
507	        // guard is dropped before touching `alias_to_primary` — so this never
508	        // holds one shard lock while acquiring the other (register_alias probes
509	        // them in the opposite order; holding across would risk a deadlock).
510	        let is_live_primary = self
511	            .models
512	            .get(model_name)
513	            .is_some_and(|existing| !existing.is_empty());
514	        if is_live_primary && !self.alias_to_primary.contains_key(model_name) {
515	            tracing::warn!(
516	                alias = model_name,
517	                namespace,
518	                "Alias collides with a registered primary model — skipping. \
519	                 Choose a different alias or rename the conflicting model."
520	            );
521	            return false;
522	        }
523	
524	        let model = self.get_or_create_model(model_name);
525	        model.add_worker_set(namespace.to_string(), worker_set);
526	        self.publish_catalog_locked();
527	        true
528	    }
529	
530	    /// Record that `alias` is an alternate name for `primary`. Used to normalize metrics labels.
531	    ///
532	    /// The claim is taken atomically through the map entry so two concurrent
533	    /// registrations of the same alias cannot both succeed. First-write-wins:
534	    /// re-registering the same alias→primary is idempotent, but a conflicting
535	    /// primary (or a name already owned by a registered primary model) is
536	    /// refused and logged so operators find the collision in the logs rather
537	    /// than through silent metric re-attribution.
538	    ///
539	    /// Holds `Self::reservation_lock` across the live-primary probe and the
540	    /// entry insert so the claim is atomic against a concurrent `add_worker_set`
541	    /// for the same name. Within that section the `models` guard is dropped before
542	    /// touching `alias_to_primary` (via `is_some_and`), and the lock is taken
543	    /// before any map access, so no DashMap shard lock is ever held across another.
544	    pub fn register_alias(&self, alias: &str, primary: &str) -> bool {
545	        let _reservation = self.reservation_lock.lock();
546	        if self
547	            .models
548	            .get(alias)
549	            .is_some_and(|model| !model.is_empty())
550	            && !self.alias_to_primary.contains_key(alias)
551	        {
552	            tracing::warn!(
553	                alias,
554	                primary,
555	                "Alias collides with a registered primary model — refusing to register. \
556	                 Choose a different alias or rename the conflicting model."
557	            );
558	            return false;
559	        }
560	
561	        match self.alias_to_primary.entry(alias.to_string()) {
562	            Entry::Occupied(existing) => {
563	                if existing.get() != primary {
564	                    tracing::warn!(
565	                        alias,
566	                        new_primary = primary,
567	                        existing_primary = existing.get().as_str(),
568	                        "Alias is already claimed by a different primary — refusing to overwrite. \
569	                         Existing claim wins."
570	                    );
571	                    return false;
572	                }
573	                // Same alias→same primary — idempotent, no-op.
574	                true
575	            }
576	            Entry::Vacant(slot) => {
577	                slot.insert(primary.to_string());
578	                self.publish_catalog_locked();
579	                true
580	            }
581	        }
582	    }
