584	    /// Remove a previously registered alias mapping once the alias has no WorkerSets.
585	    pub fn unregister_alias_if_empty(&self, alias: &str, primary: &str) {
586	        let _reservation = self.reservation_lock.lock();
587	        if self
588	            .models
589	            .get(alias)
590	            .is_some_and(|model| !model.is_empty())
591	        {
592	            return;
593	        }
594	
595	        self.alias_to_primary
596	            .remove_if(alias, |_, existing| existing == primary);
597	        self.publish_catalog_locked();
598	    }
