639	    /// Commit a complete discovery group atomically.
640	    ///
641	    pub(crate) fn commit_discovery_group(
642	        &self,
643	        group_id: &str,
644	        worker_set_key: &str,
645	        worker_set: WorkerSet,
646	        members: Vec<(String, ModelDeploymentCard)>,
647	        adapters: Vec<(String, ModelDeploymentCard)>,
648	    ) -> anyhow::Result<()> {
649	        let representative = members
650	            .first()
651	            .map(|(_, card)| card)
652	            .ok_or_else(|| anyhow::anyhow!("cannot commit an empty discovery group"))?;
653	        let primary = representative.name().to_string();
654	        let aliases = representative
655	            .aliases
656	            .iter()
657	            .filter(|alias| alias.as_str() != primary)
658	            .cloned()
659	            .collect::<Vec<_>>();
660	        let namespace = worker_set.namespace().to_string();
661	        let representative = representative.clone();
662	
663	        let _reservation = self.reservation_lock.lock();
664	        let lora_before = self.lora_projection_locked();
665	        anyhow::ensure!(
666	            !self.discovery_groups.contains_key(group_id),
667	            "discovery group {group_id:?} is already committed"
668	        );
669	        if let Some(owner) = self.alias_to_primary.get(&primary) {
670	            anyhow::bail!(
671	                "model name {primary:?} is reserved as an alias of {:?}",
672	                owner.value()
673	            );
674	        }
675	        anyhow::ensure!(
676	            !self.discovery_groups.iter().any(|entry| entry
677	                .adapters
678	                .values()
679	                .any(|adapter| adapter.name() == primary)),
680	            "model name {primary:?} is reserved by a LoRA adapter"
681	        );
682	
683	        for alias in &aliases {
684	            if let Some(owner) = self.alias_to_primary.get(alias)
685	                && owner.value() != &primary
686	            {
687	                anyhow::bail!("alias {alias:?} is already reserved by {:?}", owner.value());
688	            }
689	            let is_other_primary = self
690	                .models
691	                .get(alias)
692	                .is_some_and(|model| !model.is_empty())
693	                && self
694	                    .alias_to_primary
695	                    .get(alias)
696	                    .is_none_or(|owner| owner.value() != &primary);
697	            anyhow::ensure!(
698	                !is_other_primary,
699	                "alias {alias:?} collides with a registered primary model"
700	            );
701	        }
702	        self.validate_adapter_claims(&primary, adapters.iter().map(|(_, card)| card))?;
703	
704	        let worker_set = Arc::new(worker_set);
705	        self.get_or_create_model(&primary)
706	            .add_worker_set(worker_set_key.to_string(), worker_set.clone());
707	        for alias in &aliases {
708	            self.alias_to_primary.insert(alias.clone(), primary.clone());
709	            self.get_or_create_model(alias)
710	                .add_worker_set(worker_set_key.to_string(), worker_set.clone());
711	        }
712	        for (_, adapter) in &adapters {
713	            let adapter_view = Arc::new(worker_set.adapter_view(adapter.clone()));
714	            self.get_or_create_model(adapter.name())
715	                .add_worker_set(worker_set_key.to_string(), adapter_view);
716	        }
717	
718	        let cards = members.into_iter().collect::<HashMap<_, _>>();
719	        for (key, card) in &cards {
720	            self.cards.insert(key.clone(), Arc::new(card.clone()));
721	        }
722	        let adapters = adapters.into_iter().collect::<HashMap<_, _>>();
723	        for (key, card) in &adapters {
724	            self.cards.insert(key.clone(), Arc::new(card.clone()));
725	        }
726	        self.discovery_groups.insert(
727	            group_id.to_string(),
728	            CommittedDiscoveryGroup {
729	                primary: primary.clone(),
730	                namespace: namespace.clone(),
731	                worker_set_key: worker_set_key.to_string(),
732	                aliases,
733	                cards,
734	                adapters,
735	                representative,
736	                worker_set,
737	            },
738	        );
739	        let lora_after = self.lora_projection_locked();
740	        self.publish_lora_projection_locked(Self::union_lora_projection(&lora_before, &lora_after));
741	        self.reconcile_discovery_topology(&primary, &namespace);
742	        self.publish_catalog_locked();
743	        self.publish_lora_projection_locked(lora_after);
744	        Ok(())
745	    }
746	
747	    fn validate_adapter_claims<'a>(
748	        &self,
749	        primary: &str,
750	        adapters: impl Iterator<Item = &'a ModelDeploymentCard>,
751	    ) -> anyhow::Result<()> {
752	        for adapter in adapters {
753	            let lora = adapter
754	                .lora
755	                .as_ref()
756	                .ok_or_else(|| anyhow::anyhow!("adapter card is missing LoRA metadata"))?;
757	            anyhow::ensure!(!lora.name.is_empty(), "LoRA adapter name cannot be empty");
758	            let name = adapter.name();
759	            anyhow::ensure!(
760	                name != primary,
761	                "LoRA adapter name {name:?} collides with its base model"
762	            );
763	            anyhow::ensure!(
764	                !self.alias_to_primary.contains_key(name),
765	                "LoRA adapter name {name:?} collides with a registered alias"
766	            );
767	            let owned_by_same_base = self.discovery_groups.iter().any(|entry| {
768	                entry.primary == primary
769	                    && entry
770	                        .adapters
771	                        .values()
772	                        .any(|existing| existing.name() == name)
773	            });
774	            let collides_with_primary =
775	                self.models.get(name).is_some_and(|model| !model.is_empty()) && !owned_by_same_base;
776	            anyhow::ensure!(
777	                !collides_with_primary,
778	                "LoRA adapter name {name:?} collides with a registered model"
779	            );
780	        }
781	        Ok(())
782	    }
