784	    pub(crate) fn replace_discovery_group(
785	        &self,
786	        group_id: &str,
787	        members: Vec<(String, ModelDeploymentCard)>,
788	        adapters: Vec<(String, ModelDeploymentCard)>,
789	    ) -> anyhow::Result<()> {
790	        let _reservation = self.reservation_lock.lock();
791	        let group = self
792	            .discovery_groups
793	            .get(group_id)
794	            .ok_or_else(|| anyhow::anyhow!("committed discovery group {group_id:?} not found"))?;
795	        let primary = group.primary.clone();
796	        let worker_set_key = group.worker_set_key.clone();
797	        let worker_set = group.worker_set.clone();
798	        let previous_member_keys = group.cards.keys().cloned().collect::<HashSet<_>>();
799	        let previous_adapter_keys = group.adapters.keys().cloned().collect::<HashSet<_>>();
800	        let previous_adapter_names = group
801	            .adapters
802	            .values()
803	            .map(|card| card.name().to_string())
804	            .collect::<HashSet<_>>();
805	        drop(group);
806	
807	        anyhow::ensure!(
808	            !members.is_empty(),
809	            "cannot replace with an empty discovery group"
810	        );
811	        self.validate_adapter_claims(&primary, adapters.iter().map(|(_, card)| card))?;
812	        let members = members.into_iter().collect::<HashMap<_, _>>();
813	        let adapters = adapters.into_iter().collect::<HashMap<_, _>>();
814	        let desired_member_keys = members.keys().cloned().collect::<HashSet<_>>();
815	        let desired_adapter_keys = adapters.keys().cloned().collect::<HashSet<_>>();
816	        let desired_adapter_names = adapters
817	            .values()
818	            .map(|card| card.name().to_string())
819	            .collect::<HashSet<_>>();
820	        let adapter_views = adapters
821	            .values()
822	            .map(|card| {
823	                (
824	                    card.name().to_string(),
825	                    Arc::new(worker_set.adapter_view(card.clone())),
826	                )
827	            })
828	            .collect::<HashMap<_, _>>();
829	        let lora_before = self.lora_projection_locked();
830	
831	        for key in previous_member_keys.difference(&desired_member_keys) {
832	            self.cards.remove(key);
833	        }
834	        for key in previous_adapter_keys.difference(&desired_adapter_keys) {
835	            self.cards.remove(key);
836	        }
837	        for (key, card) in members.iter().chain(adapters.iter()) {
838	            self.cards.insert(key.clone(), Arc::new(card.clone()));
839	        }
840	
841	        let mut group = self
842	            .discovery_groups
843	            .get_mut(group_id)
844	            .ok_or_else(|| anyhow::anyhow!("committed discovery group {group_id:?} not found"))?;
845	        group.representative = members
846	            .values()
847	            .next()
848	            .cloned()
849	            .expect("non-empty members checked above");
850	        group.cards = members;
851	        group.adapters = adapters;
852	        drop(group);
853	
854	        for (name, adapter_view) in adapter_views {
855	            self.get_or_create_model(&name)
856	                .add_worker_set(worker_set_key.clone(), adapter_view);
857	        }
858	        for name in previous_adapter_names.difference(&desired_adapter_names) {
859	            if let Some(model) = self.models.get(name) {
860	                model.remove_worker_set(&worker_set_key);
861	            }
862	            self.remove_model_if_empty(name);
863	        }
864	        let lora_after = self.lora_projection_locked();
865	        self.publish_lora_projection_locked(Self::union_lora_projection(&lora_before, &lora_after));
866	        self.publish_catalog_locked();
867	        self.publish_lora_projection_locked(lora_after);
868	        Ok(())
869	    }
