878	    /// Remove a complete discovery group atomically.
879	    ///
880	    pub(crate) fn remove_discovery_group(&self, group_id: &str) -> Option<RemovedDiscoveryGroup> {
881	        let _reservation = self.reservation_lock.lock();
882	        let lora_before = self.lora_projection_locked();
883	        let (_, group) = self.discovery_groups.remove(group_id)?;
884	        let representative = group.representative.clone();
885	        let topology_namespace = group.namespace.clone();
886	
887	        for key in group.cards.keys() {
888	            self.cards.remove(key);
889	        }
890	        for key in group.adapters.keys() {
891	            self.cards.remove(key);
892	        }
893	        if let Some(model) = self.models.get(&group.primary)
894	            && let Some(worker_set) = model.remove_worker_set(&group.worker_set_key)
895	        {
896	            Self::clear_worker_set_targets(&worker_set);
897	        }
898	        self.remove_model_if_empty(&group.primary);
899	        for alias in &group.aliases {
900	            if let Some(model) = self.models.get(alias) {
901	                model.remove_worker_set(&group.worker_set_key);
902	            }
903	            self.remove_model_if_empty(alias);
904	            if self.models.get(alias).is_none_or(|model| model.is_empty()) {
905	                self.alias_to_primary
906	                    .remove_if(alias, |_, owner| owner == &group.primary);
907	            }
908	        }
909	        for adapter in group.adapters.values() {
910	            if let Some(model) = self.models.get(adapter.name()) {
911	                model.remove_worker_set(&group.worker_set_key);
912	            }
913	            self.remove_model_if_empty(adapter.name());
914	        }
915	        let cards = group
916	            .cards
917	            .into_values()
918	            .chain(group.adapters.into_values())
919	            .collect();
920	        let removed = RemovedDiscoveryGroup {
921	            representative,
922	            cards,
923	        };
924	        let lora_after = self.lora_projection_locked();
925	        self.publish_lora_projection_locked(Self::union_lora_projection(&lora_before, &lora_after));
926	        self.reconcile_discovery_topology(&group.primary, &topology_namespace);
927	        self.publish_catalog_locked();
928	        self.publish_lora_projection_locked(lora_after);
929	        Some(removed)
930	    }
