1416	    // -- Convenience methods for in-process models (http.rs, grpc.rs) --
1417	    // These create a WorkerSet with a default namespace for local models.
1418	    // Synthetic in-process worker sets are always `Aggregated` (they own
1419	    // their engine inline and don't depend on a peer worker), so we stamp
1420	    // that role onto the card here. The `Prefill` helper, in contrast,
1421	    // tags itself with `WorkerType::Prefill` so the serving-readiness
1422	    // gate sees it correctly.
1423	    // TODO: These methods use ModelDeploymentCard::default() for the WorkerSet, which means
1424	    // parsing_options() returns defaults (no tool_call_parser/reasoning_parser). Pass the real
1425	    // MDC from callers so ParsingOptions reflect the model's actual configuration.
1426	
1427	    fn aggregated_local_card() -> ModelDeploymentCard {
1428	        let mut card = ModelDeploymentCard::default();
1429	        card.worker_type = Some(crate::worker_type::WorkerType::Aggregated);
1430	        card.needs = Vec::new();
1431	        card
1432	    }
