1434	    pub fn add_chat_completions_model(
1435	        &self,
1436	        model: &str,
1437	        card_checksum: &str,
1438	        engine: OpenAIChatCompletionsStreamingEngine,
1439	    ) -> Result<(), ModelManagerError> {
1440	        let _reservation = self.reservation_lock.lock();
1441	        let model_entry = self.get_or_create_model(model);
1442	        if model_entry.has_chat_engine() {
1443	            return Err(ModelManagerError::ModelAlreadyExists(model.to_string()));
1444	        }
1445	        let namespace = format!("__local_chat_{}", model);
1446	        let mut ws = WorkerSet::new(
1447	            namespace.clone(),
1448	            card_checksum.to_string(),
1449	            Self::aggregated_local_card(),
1450	        );
1451	        ws.chat_engine = Some(engine);
1452	        model_entry.add_worker_set(namespace, Arc::new(ws));
1453	        self.publish_catalog_locked();
1454	        Ok(())
1455	    }
