1796	    /// Whether to start the LoRA load-estimator feed for a KV router's metric worker type.
1797	    ///
1798	    /// The feed must run for the worker mode that carries the routable request load. In dynamo's
1799	    /// KV path that is `WORKER_TYPE_DECODE`, which the binding assigns to BOTH aggregated and
1800	    /// disaggregated-decode endpoints (any non-prefill endpoint that tracks active blocks; see
1801	    /// `create_kv_router_from_endpoint`). Only disaggregated PREFILL is excluded, so its transient
1802	    /// load does not double-count the decode component's active sequences. Returns false when LoRA
1803	    /// serving is disabled.
1804	    fn should_start_lora_load_feed(lora_enabled: bool, worker_type: &str) -> bool {
1805	        lora_enabled && worker_type == crate::protocols::common::timing::WORKER_TYPE_DECODE
1806	    }
