1931	    #[allow(clippy::too_many_arguments)]
1932	    pub(crate) async fn kv_chooser_for_with_selector_and_client<Sel>(
1933	        &self,
1934	        endpoint: &Endpoint,
1935	        client: Client,
1936	        kv_cache_block_size: u32,
1937	        selector: Sel,
1938	        kv_router_config: Option<KvRouterConfig>,
1939	        prefill_load_estimator: Option<Arc<dyn PrefillLoadEstimator>>,
1940	        worker_role: Option<WorkerType>,
1941	        metric_worker_type: &'static str,
1942	        model_name: Option<String>,
1943	        is_eagle: bool,
1944	    ) -> anyhow::Result<Arc<KvRouter<Sel>>>
1945	    where
1946	        Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
1947	    {
1948	        let lora_domain = self.lora_domain(&endpoint.id());
1949	
1950	        // Register router via discovery mechanism.
1951	        let drt = endpoint.component().drt();
1952	        let instance_id = drt.discovery().instance_id();
1953	
1954	        // Build transport for router endpoint based on request plane mode
1955	        // Use the worker's component name so each target pool gets its own router discovery group
1956	        let router_endpoint_id =
1957	            router_endpoint_id(endpoint.id().namespace, endpoint.id().component);
1958	        let transport = build_transport_type(endpoint, &router_endpoint_id, instance_id).await?;
1959	
1960	        let discovery_spec = DiscoverySpec::Endpoint {
1961	            namespace: router_endpoint_id.namespace.clone(),
1962	            component: router_endpoint_id.component.clone(),
1963	            endpoint: router_endpoint_id.name.clone(),
1964	            transport,
1965	            device_type: None,
1966	            request_plane_codec: Some(RequestPlanePayloadCodec::configured()),
1967	        };
1968	
1969	        let registration = drt.register_endpoint_lease(discovery_spec).await?;
1970	
1971	        // Get of create runtime config watcher for this endpoint
1972	        let workers_with_configs = self.get_or_create_runtime_config_watcher(endpoint).await?;
1973	
1974	        // A selector that does not consume cache input must not create a shared-cache client or
1975	        // subscribe to its updates.
1976	        let shared_cache: Option<Box<dyn dynamo_kv_router::SharedKvCache>> = if selector
1977	            .required_worker_inputs()
1978	            .contains(WorkerInputs::CACHE)
1979	        {
1980	            match kv_router_config
1981	                .as_ref()
1982	                .map(|c| c.shared_cache_type)
1983	                .unwrap_or_default()
1984	            {
1985	                dynamo_kv_router::SharedCacheType::None => None,
1986	                dynamo_kv_router::SharedCacheType::Hicache => {
1987	                    let worker_component_name = &endpoint.id().component;
1988	                    tracing::info!(
1989	                        worker_component = worker_component_name,
1990	                        "Using HiCache shared KV cache"
1991	                    );
1992	                    Some(Box::new(
1993	                        self.hicache_cache_for(endpoint, workers_with_configs.clone()),
1994	                    ))
1995	                }
1996	            }
1997	        } else {
1998	            None
1999	        };
2000	
2001	        let effective_kv_router_config = kv_router_config.clone().unwrap_or_default();
2002	        let kv_event_source_requirement =
2003	            KvEventSourceRequirement::derive(worker_role, &effective_kv_router_config);
2004	        let cache_required = selector
2005	            .required_worker_inputs()
2006	            .contains(WorkerInputs::CACHE)
2007	            || effective_kv_router_config.serve_indexer
2008	            || matches!(
2009	                kv_event_source_requirement,
2010	                KvEventSourceRequirement::ConditionalDisaggDecodeCache
2011	                    | KvEventSourceRequirement::Unknown
2012	            );
2013	        let kv_source_membership = if cache_required
2014	            && kv_event_source_requirement.should_subscribe(&effective_kv_router_config)
2015	        {
2016	            Some(
2017	                self.get_or_create_kv_source_membership_watch(endpoint)
2018	                    .await?,
2019	            )
2020	        } else {
2021	            None
2022	        };
2023	
2024	        let mut chooser = KvRouter::new_with_worker_role(
2025	            endpoint.clone(),
2026	            client,
2027	            workers_with_configs,
2028	            kv_source_membership,
2029	            kv_cache_block_size,
2030	            selector,
2031	            kv_router_config,
2032	            prefill_load_estimator,
2033	            worker_role,
2034	            metric_worker_type,
2035	            model_name,
2036	            is_eagle,
2037	            shared_cache,
2038	            self.lora_enabled.then(|| lora_domain.filter.clone()),
2039	        )
2040	        .await?;
2041	        chooser.set_endpoint_registration(registration);
2042	
2043	        // F2: feed the LoRA LoadEstimator in KV mode. Start exactly one active-sequence
2044	        // subscription per decode endpoint. WORKER_TYPE_DECODE is the routing path for BOTH
2045	        // aggregated and disaggregated-decode deployments: the binding maps any non-prefill,
2046	        // active-block-tracking endpoint to WORKER_TYPE_DECODE (see create_kv_router_from_endpoint
2047	        // in bindings/python/rust/llm/kv.rs), so aggregated KV feeds load here too. Only
2048	        // disaggregated PREFILL is excluded — its load is transient and would double-count the
2049	        // decode component's active sequences. Without this feed the estimator is never fed in KV
2050	        // mode and every LoRA stays "inactive" forever. (Edge case specific to the Python KV path:
2051	        // create_kv_router_from_endpoint infers WORKER_TYPE_PREFILL for a non-prefill endpoint when
2052	        // router_track_active_blocks=false, so that aggregated worker would skip this feed and KV
2053	        // routing is not load-aware — dynamic LoRA allocation then degrades to cold-start pins while
2054	        // the filter still routes by loaded worker. Constructors that pass WORKER_TYPE_DECODE
2055	        // directly, e.g. the watcher / C bindings, are unaffected.)
2056	        if Self::should_start_lora_load_feed(self.lora_enabled, metric_worker_type) {
2057	            let feed_key = endpoint.id().to_string();
2058	            // Start a feed if none runs for this endpoint yet, or restart it if the previous
2059	            // one exited (so a dead subscription does not permanently disable load tracking).
2060	            //
2061	            // Use the DashMap entry API so the check-and-insert is atomic per key: two
2062	            // concurrent `kv_chooser_for` calls for the same component otherwise both observe
2063	            // "no feed" and each spawn a subscription, double-counting active sequences.
2064	            // Holding the entry lock across the spawn serializes them — the loser sees the
2065	            // winner's live handle and skips.
2066	            let started = match self.lora_load_feeds.entry(feed_key) {
2067	                Entry::Occupied(mut entry) => {
2068	                    if entry.get().is_finished() {
2069	                        // Previous feed exited; replace it (aborting the dead handle is a no-op).
2070	                        let handle = self
2071	                            .lora_domain(&endpoint.id())
2072	                            .load_estimator
2073	                            .clone()
2074	                            .start_event_subscription(endpoint.clone());
2075	                        entry.insert(handle);
2076	                        true
2077	                    } else {
2078	                        false
2079	                    }
2080	                }
2081	                Entry::Vacant(entry) => {
2082	                    let handle = self
2083	                        .lora_domain(&endpoint.id())
2084	                        .load_estimator
2085	                        .clone()
2086	                        .start_event_subscription(endpoint.clone());
2087	                    entry.insert(handle);
2088	                    true
2089	                }
2090	            };
2091	            if started {
2092	                tracing::info!(
2093	                    namespace = %endpoint.id().namespace,
2094	                    component = %endpoint.id().component,
2095	                    endpoint = %endpoint.id().name,
2096	                    "Started decode-side LoRA load feed (KV active-sequence subscription)"
2097	                );
2098	            }
2099	        }
2100	
2101	        Ok(Arc::new(chooser))
2102	    }
