2116	    fn ensure_lora_controller(&self, endpoint_id: &EndpointId, domain: &Arc<LoraEndpointDomain>) {
2117	        let Some(cancel_token) = self.lora_controller_cancel.lock().clone() else {
2118	            return;
2119	        };
2120	        if domain.controller_started.swap(true, Ordering::AcqRel) {
2121	            return;
2122	        }
2123	
2124	        let config = crate::lora::LoraAllocationConfig::from_env();
2125	        if !config.enabled {
2126	            return;
2127	        }
2128	        domain
2129	            .load_estimator
2130	            .set_config(crate::lora::LoadEstimatorConfig {
2131	                rate_window: std::time::Duration::from_secs(config.effective_rate_window_secs()),
2132	                buckets_per_second: config.buckets_per_second,
2133	                predictor_type: config.predictor_type,
2134	                ema_alpha: config.ema_alpha,
2135	                ..Default::default()
2136	            });
2137	        let domain_cancel = cancel_token.child_token();
2138	        *domain.controller_cancel.lock() = Some(domain_cancel.clone());
2139	        let _handle = crate::lora::LoraController::start_for_endpoint(
2140	            endpoint_id.clone(),
2141	            config,
2142	            domain.routing_table.clone(),
2143	            domain.state_tracker.clone(),
2144	            domain.load_estimator.clone(),
2145	            domain_cancel,
2146	        );
2147	    }
