2198	    /// Derive routing targets exclusively from committed WorkerSets. The
2199	    /// caller holds `reservation_lock`; target clearing is synchronous and
2200	    /// happens before the catalog pointer is published.
2201	    fn reconcile_discovery_topology(&self, model_name: &str, namespace: &str) {
2202	        let Some(model) = self.get_model_internal(model_name) else {
2203	            return;
2204	        };
2205	        let worker_sets = model
2206	            .worker_sets()
