2211	        let prefill_providers = worker_sets
2212	            .iter()
2213	            .filter(|worker_set| worker_set.card().worker_type == Some(WorkerType::Prefill))
2214	            .filter_map(|worker_set| worker_set.topology_endpoint().cloned())
2215	            .collect::<Vec<_>>();
2216	        let decode_consumers = worker_sets
2217	            .iter()
2218	            .filter(|worker_set| worker_set.card().worker_type == Some(WorkerType::Decode))
2219	            .collect::<Vec<_>>();
2220	        let prefill_target = (prefill_providers.len() == 1 && decode_consumers.len() == 1)
2221	            .then(|| prefill_providers[0].clone());
2222	        for worker_set in &decode_consumers {
2223	            if let Some(router) = &worker_set.prefill_router {
2224	                router.set_target(prefill_target.clone());
2225	            }
