2229	            .iter()
2230	            .filter(|worker_set| {
2231	                worker_set.card().worker_type == Some(WorkerType::Encode)
2232	                    && worker_set.card().model_type.is_empty()
2233	            })
2234	            .filter_map(|worker_set| worker_set.topology_endpoint().cloned())
2235	            .collect::<Vec<_>>();
2236	        let unique_encode = (encode_providers.len() == 1).then(|| encode_providers[0].clone());
2237	        let capable_prefill = (prefill_providers.len() == 1)
2238	            && worker_sets.iter().any(|worker_set| {
2239	                worker_set.card().worker_type == Some(WorkerType::Prefill)
2240	                    && Self::supports_encoder_result_handoff(worker_set.card())
2241	            });
