2245	                continue;
2246	            };
2247	            let routing_enabled = match worker_set.card().worker_type {
2248	                Some(WorkerType::Decode) => capable_prefill && decode_consumers.len() == 1,
2249	                Some(WorkerType::Prefill) => false,
2250	                Some(WorkerType::Aggregated | WorkerType::Encode) | None => {
2251	                    Self::supports_encoder_result_handoff(worker_set.card())
2252	                }
2253	            };
2254	            router.set_target(routing_enabled.then(|| unique_encode.clone()).flatten());
2255	        }
