2286	    /// Returns a `watch::Receiver` with the latest `HashMap<WorkerId, ModelRuntimeConfig>`.
2287	    pub async fn get_or_create_runtime_config_watcher(
2288	        &self,
2289	        endpoint: &Endpoint,
2290	    ) -> anyhow::Result<RuntimeConfigWatch> {
2291	        let endpoint_id = endpoint.id();
2292	
2293	        if let Some(existing) = self.runtime_configs.get(&endpoint_id) {
2294	            return Ok(existing.clone());
2295	        }
2296	
2297	        // Slow path: create the watch (spawns a background task).
2298	        // If another caller raced us, the entry() below picks up the winner;
2299	        // the loser's background task stops once its receivers are dropped.
2300	        // This registry is keyed by endpoint and outlives any one WorkerSet, so
2301	        // the watch is scoped to the process, not to a caller's own lifecycle.
2302	        let rx = runtime_config_watch(endpoint, endpoint.drt().primary_token()).await?;
2303	        let result = match self.runtime_configs.entry(endpoint_id) {
2304	            Entry::Occupied(e) => e.get().clone(),
2305	            Entry::Vacant(e) => {
2306	                e.insert(rx.clone());
2307	                rx
2308	            }
2309	        };
