2331	    fn get_or_create_kv_source_membership_watch_with(
2332	        &self,
2333	        serving_endpoint: EndpointId,
2334	        runtime_configs: RuntimeConfigWatch,
2335	        discovery: Arc<dyn Discovery>,
2336	    ) -> KvSourceMembershipWatch {
2337	        if let Some(existing) = self
2338	            .kv_source_memberships
2339	            .get(&serving_endpoint)
2340	            .and_then(|entry| entry.value().upgrade())
2341	        {
2342	            return existing.subscribe();
2343	        }
2344	
2345	        let candidate = KvSourceMembershipCoordinator::start(
2346	            serving_endpoint.clone(),
2347	            runtime_configs,
2348	            discovery,
2349	        );
2350	        let coordinator = match self.kv_source_memberships.entry(serving_endpoint) {
2351	            Entry::Occupied(mut entry) => match entry.get().upgrade() {
2352	                Some(existing) => existing,
2353	                None => {
2354	                    entry.insert(Arc::downgrade(&candidate));
2355	                    candidate
2356	                }
2357	            },
2358	            Entry::Vacant(entry) => {
2359	                entry.insert(Arc::downgrade(&candidate));
2360	                candidate
2361	            }
2362	        };
2363	        coordinator.subscribe()
2364	    }
