        is_eagle: bool,
    ) -> anyhow::Result<Arc<KvRouter<Sel>>>
    where
        Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
    {
        let client = endpoint.client().await?;
        self.kv_chooser_for_with_selector_and_client(
            endpoint,
            client,
            kv_cache_block_size,
            selector,
            kv_router_config,
