    };

    use crate::model_card::ModelDeploymentCard;
    use crate::{
        discovery::{KvEventSource, KvSourceStatus},
        local_model::runtime_config::ModelRuntimeConfig,
    };

    fn make_worker_set(namespace: &str, mdcsum: &str) -> WorkerSet {
        WorkerSet::new(
            namespace.to_string(),
