fn apply_event(&mut self, event: DiscoveryEvent, namespace_filter: &NamespaceFilter) {
    match event {
        DiscoveryEvent::Added(instance) => {
            match self.host.normalize(instance, namespace_filter) {
                Ok(Some(instance)) => self.apply_added(instance),
                Ok(None) => false,
                Err(error) => {
                    tracing::error!(
